# Parse the table data from the HTML in page_89.txt
with open('/app/resources/treasury_bulletin_1970_06_page_89.txt', 'r') as f:
    content = f.read()

import re
from html.parser import HTMLParser

class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_td = False
        self.in_th = False
        self.current_row = []
        self.rows = []
        self.in_table = False

    def handle_starttag(self, tag, attrs):
        if tag == 'table':
            self.in_table = True
        elif tag == 'tr':
            self.current_row = []
        elif tag == 'td' or tag == 'th':
            self.in_td = True
            self.cell_data = ""

    def handle_endtag(self, tag):
        if tag == 'table':
            self.in_table = False
        elif tag == 'tr' and self.current_row:
            self.rows.append(self.current_row)
        elif tag == 'td' or tag == 'th':
            self.in_td = False
            self.current_row.append(self.cell_data.strip())

    def handle_data(self, data):
        if self.in_td:
            self.cell_data += data

parser = TableParser()
parser.feed(content)

# Print first few rows to see the structure
print("Number of rows:", len(parser.rows))
for i, row in enumerate(parser.rows[:15]):
    print(f"Row {i}: {row[:13]}")  # First 13 columns
EOF
